// Class 12 English Core - Flamingo Prose Chapter 6: Poets and Pancakes
// Fully standardized to English Core Blueprint & AGENTS.md guidelines

export const c12EngF6HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.8; color: #E2E8F0; max-width: 950px; margin: 0 auto; padding: 12px; font-size: 15.5px;\">\n\n  <!-- Chapter Header Badge -->\n  <div style=\"background: linear-gradient(135deg, rgba(253, 200, 48, 0.22), rgba(243, 115, 53, 0.1)); border: 1.5px solid #FDC830; border-radius: 12px; padding: 20px; margin-bottom: 25px; box-shadow: 0 4px 22px rgba(253, 200, 48, 0.15);\">\n    <div style=\"display: flex; align-items: center; gap: 10px; margin-bottom: 8px;\">\n      <span style=\"background: #FDC830; color: #000; font-size: 12px; font-weight: 800; padding: 4px 10px; border-radius: 6px; letter-spacing: 0.5px;\">FLAMINGO &bull; PROSE CHAPTER 6</span>\n      <span style=\"color: #94A3B8; font-size: 13.5px; font-weight: 600;\">CLASS XII ENGLISH CORE</span>\n    </div>\n    <h1 style=\"color: #FFFFFF; font-size: 26px; font-weight: 900; margin: 0 0 6px 0; letter-spacing: -0.5px;\">Poets and Pancakes</h1>\n    <p style=\"color: #CBD5E1; font-size: 15px; margin: 0; font-style: italic;\">\n      By Asokamitran (1931&ndash;2017) &mdash; Excerpted from <i>My Years with Boss</i>: Behind the Silver Screen at Gemini Studios &mdash; Eccentricities, Satire &amp; Cultural Politics\n    </p>\n  </div>\n\n  <!-- Quick Glossary & Chapter Dossier Card -->\n  <div style=\"background: rgba(15, 23, 42, 0.92); border: 1.5px solid rgba(253, 200, 48, 0.4); border-radius: 10px; padding: 18px 20px; margin-bottom: 25px; box-shadow: 0 4px 20px rgba(0,0,0,0.35);\">\n    <h3 style=\"color: #FDC830; font-size: 18px; margin: 0 0 12px 0; display: flex; align-items: center; gap: 8px;\">\n      <span>📖</span> Quick Glossary &amp; Chapter Dossier: Poets and Pancakes\n    </h3>\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; font-size: 14px; color: #CBD5E1;\">\n      <div><b style=\"color: #FDC830;\">Author:</b> Asokamitran (Pen name of J. Thyagarajan, acclaimed Tamil author)</div>\n      <div><b style=\"color: #FDC830;\">Source Text:</b> <i>My Years with Boss</i> (Memoir of working at Gemini Studios)</div>\n      <div><b style=\"color: #FDC830;\">Gemini Studios:</b> Iconic Madras film studio established in 1940 by S.S. Vasan</div>\n      <div><b style=\"color: #FDC830;\">Pancake:</b> Heavy cosmetic cake foundation bought in truckloads for actors</div>\n      <div><b style=\"color: #FDC830;\">Kothamangalam Subbu:</b> Versatile, creative \"Number Two\" at Gemini Studios</div>\n      <div><b style=\"color: #FDC830;\">The Office Boy:</b> Frustrated 40-year-old aspiring director relegated to slapping paint on crowds</div>\n      <div><b style=\"color: #FDC830;\">The Legal Adviser:</b> Lawyer in Story Department who inadvertently ruined a budding actress's career</div>\n      <div><b style=\"color: #FDC830;\">Stephen Spender:</b> English poet whose perplexing speech was decoded years later via <i>The God That Failed</i></div>\n    </div>\n  </div>\n\n  <!-- Section 1: Executive Summary & Historical Framework -->\n  <h2 style=\"color: #FDC830; font-size: 20px; font-weight: 800; border-bottom: 2px solid #FDC830; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    1. Executive Summary &amp; Historical Context\n  </h2>\n  <p>\n    In <b style=\"color: #FDC830;\">Poets and Pancakes</b>, acclaimed Tamil literary maestro <b style=\"color: #FDC830;\">Asokamitran</b> offers a delightfully witty, affectionately satirical memoir of his years at <b style=\"color: #FDC830;\">Gemini Studios</b> in Madras (Chennai). Founded in 1940 by visionary media entrepreneur S.S. Vasan, Gemini Studios was one of post-independence India's most influential film production houses, shaping popular culture across South India and beyond.\n  </p>\n  <p>\n    Asokamitran's role was famously modest: seated in a tiny cubicle, he spent his days tearing newspaper clippings and filing them. Because his labor lacked heavy physical exertion, he became the unwitting recipient of endless lectures from everyone in the studio. Through understated irony, Asokamitran demystifies the glitz of cinema, exposing the comical studio hierarchies, creative jealousies, ideological naivety during the Cold War, and the absurd cultural gulf between high Western literature and ordinary Madras film hands.\n  </p>\n\n  <!-- Section 2: Narrative Progression & Key Milestones -->\n  <h2 style=\"color: #FDC830; font-size: 20px; font-weight: 800; border-bottom: 2px solid #FDC830; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    2. Deep Narrative Progression: Life Inside Gemini Studios\n  </h2>\n\n  <h3 style=\"color: #FDC830; font-size: 17px; margin: 20px 0 10px 0;\">(i) The Make-Up Department: Fiery Misery &amp; National Integration</h3>\n  <p>\n    The chapter opens with the make-up department, which consumed truckloads of <b style=\"color: #FDC830;\">Pancake</b> &mdash; a heavy cosmetic foundation used by legendary actresses like Greta Garbo and Vyjayanthimala. The department was housed on the upper floor of a building believed to have once been Robert Clive's stables. The room was fitted with half a dozen large mirrors surrounded by blazing incandescent lights at all angles, subjecting actors to what Asokamitran termed <i>\"fiery misery\"</i>.\n  </p>\n  <p>\n    Long before All India Radio (AIR) and Doordarshan broadcasted programs on <b style=\"color: #FDC830;\">National Integration</b>, the Gemini make-up department practiced it organically. First headed by a Bengali, leadership passed to a Maharashtrian assisted by a Dharwar Kannadiga, an Andhra, a Madras Christian, an Anglo-Burmese, and local Tamils. The department followed a strict hierarchy: the chief make-up artist transformed the lead actors into \"hideous crimson monsters\"; the senior assistant tackled the second hero; the junior assistant made up the comedian; while the forty-year-old <b style=\"color: #FDC830;\">Office Boy</b> mixed paint in a giant vat and slapped it onto the faces of crowd players.\n  </p>\n  <p>\n    This frustrated Office Boy harbored deep bitterness: having joined decades earlier with dreams of becoming a star actor, director, or lyricist, he felt his genius was smothered, blaming all his misfortunes on the studio's Number Two, Kothamangalam Subbu.\n  </p>\n\n  <h3 style=\"color: #FDC830; font-size: 17px; margin: 20px 0 10px 0;\">(ii) Kothamangalam Subbu: The Indispensable Genius</h3>\n  <p>\n    Next to the Boss (S.S. Vasan), the most influential figure was <b style=\"color: #FDC830;\">Kothamangalam Subbu</b>. Though lacking formal higher education, Subbu was tailor-made for cinema. Whenever the Boss was stuck for a scene, Subbu instantly offered four workable alternatives; if those were rejected, he provided fourteen more!\n  </p>\n  <p>\n    Subbu gave Gemini Studios its creative identity during its golden age. He was also an accomplished poet, lyricist, and novelist who authored the celebrated Tamil novel <i>Thillana Mohanambal</i>, which brilliantly reconstructed Devadasi traditions. Despite being generous and housing dozens of relatives, his proximity to power earned him enemies like the envious Office Boy.\n  </p>\n\n  <h3 style=\"color: #FDC830; font-size: 17px; margin: 20px 0 10px 0;\">(iii) The Legal Adviser: The Unwitting Destroyer</h3>\n  <p>\n    In the Story Department sat the <b style=\"color: #FDC830;\">Legal Adviser</b>. While officially employed to provide legal counsel, everyone regarded him as the exact opposite.\n  </p>\n  <p>\n    Once, a talented young actress threw a fiery tantrum on set against the producer. While everyone stood frozen in panic, the lawyer calmly pressed the recording button of his microphone. When the actress paused for breath, he played back the recording of her shrill, unedited outburst. Hearing her own voice naked and furious shocked the young woman so profoundly that she never recovered her confidence, prematurely ending a brilliant career.\n  </p>\n  <p>\n    Unlike other employees who wore traditional khadi dhotis and kurtas, the lawyer wore Western trousers, a tie, and a coat, looking lonely and detached. When the Story Department was eventually closed down, the lawyer lost his job &mdash; the unique historical instance where a lawyer was dismissed because poets were told to go home!\n  </p>\n\n  <h3 style=\"color: #FDC830; font-size: 17px; margin: 20px 0 10px 0;\">(iv) Frank Buchman’s MRA: Flawless Sets &amp; Covert Propaganda</h3>\n  <p>\n    In 1952, Frank Buchman’s <b style=\"color: #FDC830;\">Moral Re-Armament Army (MRA)</b>, a 200-strong troupe representing twenty nationalities, visited Madras. Hosted warmly by Gemini Studios, they staged two plays: <i>Jotham Valley</i> and <i>The Forgotten Factor</i>.\n  </p>\n  <p>\n    Although their political sermons were simple, their stagecraft, costumes, and lighting were breathtaking. Their sunrise and sunset scenes &mdash; staged on a bare stage with a white backdrop and a solitary flute tune &mdash; were imitated across Tamil theater for decades. Only much later did the studio realize that the MRA was a sophisticated international anti-communist propaganda apparatus, welcomed because S.S. Vasan and the Madras elite held anti-communist sympathies.\n  </p>\n\n  <h3 style=\"color: #FDC830; font-size: 17px; margin: 20px 0 10px 0;\">(v) Stephen Spender's Visit: The Mystery of The God That Failed</h3>\n  <p>\n    Soon after, Gemini Studios welcomed a distinguished English poet and editor. The studio rolled out the red carpet, though nobody knew who he was. S.S. Vasan delivered a generic speech about freedom, after which the guest delivered an impassioned hour-long lecture on the thrills and travails of a poet.\n  </p>\n  <p>\n    To an audience of Tamil clerks, make-up men, and actors who understood only basic English, his polished British accent and esoteric literary references were utterly unintelligible. The event ended in complete mutual bewilderment.\n  </p>\n  <p>\n    Years later, after leaving the studio, Asokamitran was browsing a pavement bookstall outside the Madras post office. He bought a copy of <b style=\"color: #FDC830;\">The God That Failed</b> for fifty paise &mdash; a collection of essays by six prominent intellectuals (Arthur Koestler, Ignazio Silone, André Gide, Richard Wright, Louis Fischer, and Stephen Spender) detailing their disillusionment with Communism. Seeing the name <b style=\"color: #FDC830;\">Stephen Spender</b>, the mystery unraveled: the unheralded poet who had baffled Gemini Studios years ago was the renowned editor of <i>The Encounter</i> and anti-communist essayist Stephen Spender!\n  </p>\n\n  <!-- Section 3: Literary Devices Master Table -->\n  <h2 style=\"color: #FDC830; font-size: 20px; font-weight: 800; border-bottom: 2px solid #FDC830; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    3. Literary &amp; Rhetorical Devices Master Table\n  </h2>\n  <div style=\"overflow-x: auto; margin-bottom: 25px;\">\n    <table style=\"width: 100%; border-collapse: collapse; font-size: 14px; text-align: left; background: rgba(15, 23, 42, 0.9); border-radius: 8px; overflow: hidden;\">\n      <thead>\n        <tr style=\"background: rgba(253, 200, 48, 0.25); color: #FFFFFF; border-bottom: 2px solid #FDC830;\">\n          <th style=\"padding: 12px 14px;\">Literary Device</th>\n          <th style=\"padding: 12px 14px;\">Textual Quote / Example</th>\n          <th style=\"padding: 12px 14px;\">Thematic Function &amp; Critical Impact</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #FDC830;\">Satire &amp; Humor</td>\n          <td style=\"padding: 10px 14px;\">\"Made any decent-looking person into a hideous crimson hued monster with truckloads of pancake.\"</td>\n          <td style=\"padding: 10px 14px; color: #CBD5E1;\">Playfully punctures the artificiality and excessive cosmetic transformations of early Indian cinema.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #FDC830;\">Irony</td>\n          <td style=\"padding: 10px 14px;\">\"An English poet addressing Tamil cinema staff who knew only a few words of English...\"</td>\n          <td style=\"padding: 10px 14px; color: #CBD5E1;\">Exposes the absurd cultural and linguistic chasm between elite British poetry and Madras cinema workers.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #FDC830;\">Metaphor</td>\n          <td style=\"padding: 10px 14px;\">\"Fiery misery\"</td>\n          <td style=\"padding: 10px 14px; color: #CBD5E1;\">Evokes the intense physical heat and discomfort radiating from incandescent bulbs in the make-up room.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #FDC830;\">Situational Irony</td>\n          <td style=\"padding: 10px 14px;\">The Legal Adviser causes the ruin of an actress’s career instead of protecting her.</td>\n          <td style=\"padding: 10px 14px; color: #CBD5E1;\">Subverts the protective function of legal counsel into an accidental instrument of professional destruction.</td>\n        </tr>\n        <tr>\n          <td style=\"padding: 10px 14px; font-weight: bold; color: #FDC830;\">Understatement</td>\n          <td style=\"padding: 10px 14px;\">\"The lawyer was dismissed because poets were told to go home.\"</td>\n          <td style=\"padding: 10px 14px; color: #CBD5E1;\">Highlights the bizarre bureaucratic anomalies of film studio administration through deadpan humor.</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n\n  <!-- Section 4: Thematic Pillars -->\n  <h2 style=\"color: #FDC830; font-size: 20px; font-weight: 800; border-bottom: 2px solid #FDC830; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    4. Core Thematic Pillars &amp; Sociological Insights\n  </h2>\n  <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 14px;\">\n    <div style=\"background: rgba(253, 200, 48, 0.08); border-left: 4px solid #FDC830; padding: 14px; border-radius: 6px;\">\n      <h4 style=\"color: #FFFFFF; margin: 0 0 6px 0; font-size: 15.5px;\">Demystification of Cinema</h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 13.5px;\">Punctures celluloid glamour to reveal the mundane, chaotic labor of make-up artists, clerks, and writers.</p>\n    </div>\n    <div style=\"background: rgba(253, 200, 48, 0.08); border-left: 4px solid #FDC830; padding: 14px; border-radius: 6px;\">\n      <h4 style=\"color: #FFFFFF; margin: 0 0 6px 0; font-size: 15.5px;\">Cold War Cultural Politics</h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 13.5px;\">Shows how international anti-communist movements (MRA, Stephen Spender) co-opted politically innocent Indian studios.</p>\n    </div>\n    <div style=\"background: rgba(253, 200, 48, 0.08); border-left: 4px solid #FDC830; padding: 14px; border-radius: 6px;\">\n      <h4 style=\"color: #FFFFFF; margin: 0 0 6px 0; font-size: 15.5px;\">Humorous Studio Hierarchies</h4>\n      <p style=\"margin: 0; color: #CBD5E1; font-size: 13.5px;\">Depicts the tragicomic rivalries between frustrated office boys and indispensable geniuses like Kothamangalam Subbu.</p>\n    </div>\n  </div>\n\n</div>\n";

export const c12EngF6HtmlSolutions = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.8; color: #E2E8F0; max-width: 950px; margin: 0 auto; padding: 12px; font-size: 15.5px;\">\n\n  <!-- Solutions Header Badge -->\n  <div style=\"background: linear-gradient(135deg, rgba(253, 200, 48, 0.22), rgba(243, 115, 53, 0.1)); border: 1.5px solid #FDC830; border-radius: 12px; padding: 20px; margin-bottom: 25px; box-shadow: 0 4px 22px rgba(253, 200, 48, 0.15);\">\n    <div style=\"display: flex; align-items: center; gap: 10px; margin-bottom: 8px;\">\n      <span style=\"background: #FDC830; color: #000; font-size: 12px; font-weight: 800; padding: 4px 10px; border-radius: 6px; letter-spacing: 0.5px;\">QUESTION BANK &bull; CHAPTER 6</span>\n      <span style=\"color: #94A3B8; font-size: 13.5px; font-weight: 600;\">CLASS XII ENGLISH CORE</span>\n    </div>\n    <h1 style=\"color: #FFFFFF; font-size: 24px; font-weight: 900; margin: 0 0 6px 0;\">Poets and Pancakes &mdash; Complete Board Solutions</h1>\n    <p style=\"color: #CBD5E1; font-size: 14.5px; margin: 0;\">\n      Standardized for CBSE &amp; JKBOSE • High-Scoring Extract, Short, Long Thematic &amp; Official NCERT Solutions\n    </p>\n  </div>\n\n  <!-- SECTION A: EXTRACT-BASED QUESTIONS -->\n  <h2 style=\"color: #FDC830; font-size: 20px; font-weight: 800; border-bottom: 2px solid #FDC830; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    SECTION A: Extract-Based Questions (16 Questions | 4 Extracts)\n  </h2>\n\n  <!-- Extract 1 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(253, 200, 48, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #FDC830;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #FDC830;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"Pancake was the brand name of the make-up material that Gemini Studios bought in truck-loads. Greta Garbo must have used it, Miss Gohar must have used it, Vyjayanthimala must also have used it but Rati Agnihotri may not have even heard of it. The make-up department of the Gemini Studios was in the upstairs of a building that was believed to have been Robert Clive’s stables.\"\n    </p>\n    \n    <p>\n      <b style=\"color: #FDC830; font-size: 15px;\">Q1: What was 'Pancake' in the context of Gemini Studios?</b><br/>\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> The popular brand of cosmetic cake make-up purchased in massive truckloads to coat actors' faces heavily.\n    </p>\n\n    <p>\n      <b style=\"color: #FDC830; font-size: 15px;\">Q2: Why does the author mention that Rati Agnihotri may never have heard of Pancake?</b><br/>\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> To highlight the chronological passage of time and generational shifts in cinema technology and cosmetic products.\n    </p>\n\n    <p>\n      <b style=\"color: #FDC830; font-size: 15px;\">Q3: What historical association did the building housing the make-up department possess?</b><br/>\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> It was believed to have served as the stables of the British military commander Robert Clive.\n    </p>\n\n    <p>\n      <b style=\"color: #FDC830; font-size: 15px;\">Q4: What literary tone characterizes the author’s narration in this extract?</b><br/>\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> Lighthearted, satirical, and mildly ironic.\n    </p>\n  </div>\n\n  <!-- Extract 2 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(253, 200, 48, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #FDC830;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #FDC830;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"Subbu was the number two at Gemini Studios. He couldn't have had a more encouraging opening in films than our grown-up make-up boy had. On the contrary he must have had to face more uncertain and difficult times, for when he began there were no firmly established film producing companies or studios. Even in the matter of education, specially formal education, Subbu couldn't have had an appreciable lead over our boy.\"\n    </p>\n    \n    <p>\n      <b style=\"color: #FDC830; font-size: 15px;\">Q5: Who was considered 'Number Two' at Gemini Studios?</b><br/>\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> Kothamangalam Subbu, second in authority and influence only to the Boss, S.S. Vasan.\n    </p>\n\n    <p>\n      <b style=\"color: #FDC830; font-size: 15px;\">Q6: Who envied Subbu’s position and success intensely?</b><br/>\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> The forty-year-old Office Boy of the make-up department.\n    </p>\n\n    <p>\n      <b style=\"color: #FDC830; font-size: 15px;\">Q7: Did Subbu enjoy any educational superiority over the office boy?</b><br/>\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> No; he possessed no notable formal education and entered cinema when production was completely unorganized.\n    </p>\n\n    <p>\n      <b style=\"color: #FDC830; font-size: 15px;\">Q8: What innate quality allowed Subbu to excel beyond everyone else?</b><br/>\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> His boundless resourcefulness, spontaneous creative versatility, and cheerful loyalty.\n    </p>\n  </div>\n\n  <!-- Extract 3 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(253, 200, 48, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #FDC830;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #FDC830;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"An extremely talented actress, who was also extremely temperamental, once blew over on the sets. While everyone stood stunned, the lawyer quietly switched on the recording equipment. When the actress paused for breath, the lawyer said to her through the mike, 'One minute, please,' and played back the recording. There was nothing incriminating or unmentionably foul in the actress’s diatribe against the producer. But when she heard her voice again through the sound equipment, she was struck dumb.\"\n    </p>\n    \n    <p>\n      <b style=\"color: #FDC830; font-size: 15px;\">Q9: What triggered the actress's outburst on the set?</b><br/>\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> Her highly temperamental nature led her into a heated emotional diatribe against the producer.\n    </p>\n\n    <p>\n      <b style=\"color: #FDC830; font-size: 15px;\">Q10: How did the lawyer react while everyone else stood stunned?</b><br/>\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> He calmly switched on the recording equipment, captured her tirade, and played it back to her.\n    </p>\n\n    <p>\n      <b style=\"color: #FDC830; font-size: 15px;\">Q11: What psychological effect did hearing the playback have on the actress?</b><br/>\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> She was struck dumb with acute humiliation; hearing her uncensored anger destroyed her confidence.\n    </p>\n\n    <p>\n      <b style=\"color: #FDC830; font-size: 15px;\">Q12: What was the permanent consequence of this incident on her career?</b><br/>\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> She never acted again, prematurely ending a brilliant and promising cinematic career.\n    </p>\n  </div>\n\n  <!-- Extract 4 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(253, 200, 48, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #FDC830;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #FDC830;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"Finally, the Boss gave a speech. It was obvious that he knew no more about the visitor than the rest of us did. He spoke of freedom and democracy in the most general terms. Then the poet spoke. He couldn’t have addressed a more dazed and silent audience &mdash; no one knew what he was talking about and his accent defeated any attempt to understand what he said.\"\n    </p>\n    \n    <p>\n      <b style=\"color: #FDC830; font-size: 15px;\">Q13: Who was the distinguished visitor addressed as 'the poet'?</b><br/>\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> Stephen Spender, the noted English poet and editor of <i>The Encounter</i>.\n    </p>\n\n    <p>\n      <b style=\"color: #FDC830; font-size: 15px;\">Q14: What was peculiar about the Boss's welcoming speech?</b><br/>\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> It was vague and generic, proving that the Boss himself had no real idea of who the visitor was.\n    </p>\n\n    <p>\n      <b style=\"color: #FDC830; font-size: 15px;\">Q15: Why was the audience completely dazed and silent during the speech?</b><br/>\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> Because the audience was composed of Tamil film workers who could not comprehend his British accent or high literary discourse.\n    </p>\n\n    <p>\n      <b style=\"color: #FDC830; font-size: 15px;\">Q16: How did the session conclude?</b><br/>\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> In complete mutual bewilderment, with both speaker and audience baffled by the encounter.\n    </p>\n  </div>\n\n  <!-- SECTION B: SHORT ANSWER QUESTIONS -->\n  <h2 style=\"color: #FDC830; font-size: 20px; font-weight: 800; border-bottom: 2px solid #FDC830; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    SECTION B: Short Answer Questions (3 Marks Each | 40&ndash;50 Words)\n  </h2>\n\n  <!-- Q17 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q17: What does the author mean by 'the fiery misery' in the make-up department?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> The make-up room was equipped with half a dozen large mirrors encircled by blazing incandescent bulbs at all angles. The intense heat radiating from these lights caused excruciating physical misery to actors undergoing hours of cosmetic application.\n    </p>\n  </div>\n\n  <!-- Q18 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q18: How did the make-up department represent national integration before AIR and Doordarshan?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> The department was headed first by a Bengali, succeeded by a Maharashtrian, assisted by a Dharwar Kannadiga, an Andhra, a Madras Christian, an Anglo-Burmese, and local Tamils &mdash; embodying harmonious cross-cultural unity long before state broadcasts.\n    </p>\n  </div>\n\n  <!-- Q19 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q19: What was the specific hierarchy maintained in the make-up department?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> The chief make-up artist transformed lead actors into hideous crimson monsters; the senior assistant handled the second hero; the junior assistant made up the comedian; and the office boy slapped paint onto the crowd players.\n    </p>\n  </div>\n\n  <!-- Q20 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q20: Why was the office boy in the make-up department deeply frustrated?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> In his late forties, he had entered Gemini Studios decades earlier aspiring to become a star actor, director, or lyricist. Instead, he was relegated to slapping paint on crowds from a giant vat, blaming Subbu for his thwarted ambition.\n    </p>\n  </div>\n\n  <!-- Q21 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q21: What was Asokamitran’s specific job at Gemini Studios, and why did colleagues lecture him?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> Asokamitran sat in a cubicle cutting newspaper clippings on diverse subjects and filing them. Because his task involved no visible physical exertion, everyone assumed he was idling and offered him unsolicited lectures.\n    </p>\n  </div>\n\n  <!-- Q22 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q22: Why was Kothamangalam Subbu considered indispensable to the Boss?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> Subbu was remarkably creative, loyal, and resourceful. Whenever the Boss was stuck for a scene, Subbu instantly generated multiple viable alternatives, providing customized artistic solutions on command.\n    </p>\n  </div>\n\n  <!-- Q23 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q23: How did the Legal Adviser unwittingly extinguish a talented actress's career?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> When a temperamental actress threw a tantrum against the producer, the lawyer quietly recorded her voice and played it back. Hearing her uncensored shrillness humiliated her so deeply that she lost all confidence and never acted again.\n    </p>\n  </div>\n\n  <!-- Q24 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q24: Why did the Legal Adviser look out of place among other Gemini Studio staff?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> While all other writers, poets, and technicians wore loose khadi dhotis and kurtas, the lawyer wore Western trousers, a collar, a tie, and a coat, appearing isolated, cold, and detached.\n    </p>\n  </div>\n\n  <!-- Q25 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q25: What lasting impression did Frank Buchman’s MRA leave on Madras drama?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> The MRA staged two plays whose magnificent stagecraft and lighting &mdash; particularly sunrise and sunset scenes on a bare stage with a white backdrop and flute melody &mdash; were copied in Tamil theater for decades.\n    </p>\n  </div>\n\n  <!-- Q26 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q26: Why was Stephen Spender's visit an exercise in total mutual bewilderment?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> Spender spoke in an elite British accent about the esoteric struggles of English poetry to Tamil film workers who understood only basic English, leaving both parties utterly perplexed.\n    </p>\n  </div>\n\n  <!-- Q27 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q27: How did Asokamitran solve the mystery of the English poet years later?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> Browsing a pavement bookstall, he bought <i>The God That Failed</i> for fifty paise and saw Stephen Spender listed as an author, connecting him to the mysterious English visitor at Gemini Studios.\n    </p>\n  </div>\n\n  <!-- Q28 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q28: What ironical paradox surrounded the closure of the Story Department?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> When the Boss decided to shut down the Story Department, the Legal Adviser also lost his post &mdash; making it the unique historical instance where a lawyer was dismissed because poets were told to go home.\n    </p>\n  </div>\n\n  <!-- SECTION C: LONG ANSWER QUESTIONS -->\n  <h2 style=\"color: #FDC830; font-size: 20px; font-weight: 800; border-bottom: 2px solid #FDC830; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    SECTION C: Long Answer Questions (6 Marks Each | 120&ndash;150 Words)\n  </h2>\n\n  <!-- Q29 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(253, 200, 48, 0.3); border-radius: 8px; padding: 18px; margin-bottom: 22px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16.5px; margin: 0 0 10px 0; font-weight: 800;\">Q29: Provide a comprehensive character sketch of Kothamangalam Subbu, detailing his creative versatility, loyalty, and detractors.</h4>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.8;\">\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #FDC830;\">Introduction &amp; Studio Stature:</b><br/>\n        Kothamangalam Subbu stood out as the undisputed 'Number Two' and creative powerhouse of Gemini Studios, second in influence only to the Boss, S.S. Vasan.\n      </p>\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #FDC830;\">Versatility &amp; Creative Resourcefulness:</b><br/>\n        A man of humble Brahmin background without formal college education, Subbu was tailor-made for cinema. Whenever a scene stalled, Subbu effortlessly generated four alternative angles, and if those failed, fourteen more. He acted secondary roles with flair, wrote intricate songs, and authored the acclaimed novel <i>Thillana Mohanambal</i>, which brilliantly captured early 20th-century Devadasi traditions. In addition, his home was a refuge for dozens of distant relatives whom he fed and supported unconditionally.\n      </p>\n      <p style=\"margin: 0;\">\n        <b style=\"color: #FDC830;\">Detractors &amp; Envy:</b><br/>\n        Yet, his sycophantic proximity to the Boss and effortless brilliance earned him bitter enemies, most notably the frustrated make-up office boy who attributed every failure to Subbu's favoritism.\n      </p>\n    </div>\n  </div>\n\n  <!-- Q30 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(253, 200, 48, 0.3); border-radius: 8px; padding: 18px; margin-bottom: 22px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16.5px; margin: 0 0 10px 0; font-weight: 800;\">Q30: Analyze the quiet irony and humor in Asokamitran’s portrayal of the political naivety at Gemini Studios during the visits of the MRA and Stephen Spender.</h4>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.8;\">\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #FDC830;\">Cold War Context:</b><br/>\n        Asokamitran’s prose sparkles with understated satire when depicting the political innocence of Gemini Studios during the global Cold War.\n      </p>\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #FDC830;\">The MRA &amp; Spender Visits:</b><br/>\n        When Frank Buchman’s Moral Re-Armament Army (MRA) staged plays with breathtaking lighting and sets, the studio hosted them lavishly, completely oblivious to the fact that the MRA was an anti-communist propaganda apparatus. This naivety peaked during Stephen Spender’s visit. S.S. Vasan delivered a generic speech praising freedom, after which Spender spoke for an hour on the travails of English poetry to Tamil workers who knew only rudimentary English.\n      </p>\n      <p style=\"margin: 0;\">\n        <b style=\"color: #FDC830;\">The Ultimate Revelation:</b><br/>\n        The mutual bewilderment was resolved years later when Asokamitran bought <i>The God That Failed</i>, realizing that Spender had been invited solely because he was an anti-communist author, not for literary reasons.\n      </p>\n    </div>\n  </div>\n\n  <!-- Q31 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(253, 200, 48, 0.3); border-radius: 8px; padding: 18px; margin-bottom: 22px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16.5px; margin: 0 0 10px 0; font-weight: 800;\">Q31: How does Asokamitran use gentle satire to demystify the glamorous facade of the Indian film industry?</h4>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.8;\">\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #FDC830;\">Puncturing Celluloid Glamour:</b><br/>\n        Instead of romanticizing the silver screen, Asokamitran exposes the unglamorous, comical realities of movie-making.\n      </p>\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #FDC830;\">The Mechanics Behind the Scenes:</b><br/>\n        He portrays the make-up department as a medieval torture chamber housed in Robert Clive’s stables, where incandescent lights emit \"fiery misery\" and artists turn actors into crimson monsters with truckloads of pancake. He satirizes the rigid hierarchy where the frustrated office boy mixes paint in giant vats to slap it on crowd players, dreaming delusions of directorial greatness.\n      </p>\n      <p style=\"margin: 0;\">\n        <b style=\"color: #FDC830;\">The Absurd Administrative Realities:</b><br/>\n        He highlights the Legal Adviser whose recording destroyed an actress's career, and poets who donned khadi purely out of trend. Through affectionate humor, Asokamitran transforms the film studio into a miniature human comedy.\n      </p>\n    </div>\n  </div>\n\n  <!-- Q32 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(253, 200, 48, 0.3); border-radius: 8px; padding: 18px; margin-bottom: 22px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16.5px; margin: 0 0 10px 0; font-weight: 800;\">Q32: Examine the role and character of the Legal Adviser in Gemini Studios.</h4>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.8;\">\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #FDC830;\">Anomalous Presence:</b><br/>\n        Employed in the Story Department to provide legal advice, the lawyer was an oddity. While all other staff wore khadi kurtas, he wore Western trousers, a tie, and a coat, looking alienated and clinical.\n      </p>\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #FDC830;\">The Destruction of a Career:</b><br/>\n        His legal mind proved disastrous when applied to artistic temperaments. By recording a young actress's emotional tantrum and playing it back, he unwittingly destroyed her confidence and permanently ended her career.\n      </p>\n      <p style=\"margin: 0;\">\n        <b style=\"color: #FDC830;\">The Comical Exit:</b><br/>\n        His career at the studio ended in ironic fashion: when the Boss closed the Story Department, the lawyer was also dismissed, marking the singular event of a lawyer losing his livelihood because poets were fired.\n      </p>\n    </div>\n  </div>\n\n  <!-- Q33 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(253, 200, 48, 0.3); border-radius: 8px; padding: 18px; margin-bottom: 22px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16.5px; margin: 0 0 10px 0; font-weight: 800;\">Q33: How does Asokamitran portray the frustration of the Office Boy, and what does it reveal about human ambition?</h4>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.8;\">\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #FDC830;\">Thwarted Ambition:</b><br/>\n        The forty-year-old Office Boy is a poignant portrait of unfulfilled artistic ambition. Entering Gemini Studios with dreams of literary and directorial stardom, he found himself confined to mixing paint for crowd players.\n      </p>\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #FDC830;\">Projection of Failure:</b><br/>\n        Unable to accept his own mediocrity or bad luck, he projected his resentment onto Subbu, viewing Subbu's success as the result of sycophancy rather than genuine versatility.\n      </p>\n      <p style=\"margin: 0;\">\n        <b style=\"color: #FDC830;\">Sociological Insight:</b><br/>\n        Through the Office Boy, Asokamitran illustrates the tragicomic plight of countless aspirants drawn to the magnetic flame of the film industry, only to be reduced to peripheral cogs in the machinery.\n      </p>\n    </div>\n  </div>\n\n  <!-- Q34 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(253, 200, 48, 0.3); border-radius: 8px; padding: 18px; margin-bottom: 22px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16.5px; margin: 0 0 10px 0; font-weight: 800;\">Q34: Explain the literary and thematic significance of the book 'The God That Failed' in unraveling the mystery of Stephen Spender.</h4>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; line-height: 1.8;\">\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #FDC830;\">The Baffling Enigma:</b><br/>\n        Stephen Spender’s visit to Gemini Studios was an absolute riddle. Why had a top English poet addressed Tamil cinema staff who couldn't understand a word?\n      </p>\n      <p style=\"margin: 0 0 10px 0;\">\n        <b style=\"color: #FDC830;\">The Discovery:</b><br/>\n        Years later, Asokamitran bought a cheap copy of <i>The God That Failed</i>, an anthology by six eminent intellectuals describing their disillusionment with Communism. Seeing Spender's name alongside Louis Fischer and Richard Wright, the puzzle fell into place.\n      </p>\n      <p style=\"margin: 0;\">\n        <b style=\"color: #FDC830;\">The Revelation:</b><br/>\n        The visit had nothing to do with poetry; it was part of an international anti-communist campaign. Spender had visited Madras because S.S. Vasan was an anti-communist media mogul, bringing the Cold War into comic intersection with Indian cinema.\n      </p>\n    </div>\n  </div>\n\n  <!-- SECTION D: NCERT TEXTBOOK EXERCISES -->\n  <h2 style=\"color: #FDC830; font-size: 20px; font-weight: 800; border-bottom: 2px solid #FDC830; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    SECTION D: NCERT Textbook Exercises (Think As You Read &amp; Understanding The Text)\n  </h2>\n\n  <!-- Q35 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q35: What does the writer mean by 'the fiery misery' of those subjected to make-up?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> It refers to the physical agony and intense heat endured by actors sitting under dozens of incandescent lightbulbs positioned around large mirrors in the make-up department.\n    </p>\n  </div>\n\n  <!-- Q36 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q36: What is the example of national integration that the author refers to?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> The make-up department was headed by a Bengali, succeeded by a Maharashtrian, assisted by a Kannadiga, an Andhra, a Madras Christian, an Anglo-Burmese, and local Tamils, working together harmoniously.\n    </p>\n  </div>\n\n  <!-- Q37 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q37: What work did the 'office boy' do in the Gemini Studios? Why did he join the studios?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> He slapped liquid pancake paint onto the faces of crowd players during large shooting sessions. He had joined decades earlier hoping to become a star actor, screenwriter, director, or lyricist.\n    </p>\n  </div>\n\n  <!-- Q38 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #FDC830;\">\n    <h4 style=\"color: #FDC830; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q38: How did the author discover who the English visitor to the studios was?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #FDC830; font-weight: bold;\">✓ Answer:</span> Years later, he bought a low-priced book titled <i>The God That Failed</i> from a pavement stall and saw Stephen Spender's name as one of the authors, instantly identifying the mystery visitor.\n    </p>\n  </div>\n\n</div>\n";

